<?php get_header();while(have_posts()):the_post();$c=get_the_category();?><main id="main" class="canvas single-post"><article <?php post_class(); ?>><header class="article-head"><p class="eyebrow">LOG / <?php echo esc_html($c?$c[0]->name:'JOURNAL');?> / <?php echo esc_html(get_the_date('Y.m.d'));?></p><h1><?php the_title();?></h1><?php if(has_excerpt()):?><p class="lead"><?php echo esc_html(get_the_excerpt());?></p><?php endif;?></header><div class="article-content"><?php the_content();wp_link_pages(array('before'=>'<nav class="post-pages" aria-label="Post pages">','after'=>'</nav>','link_before'=>'<span class="post-page-num">','link_after'=>'</span>'));?></div><?php if(get_the_tag_list()):?><div class="article-tags"><?php echo get_the_tag_list('<span class="label">Tags</span>',' ');?></div><?php endif;the_post_navigation(array('prev_text'=>'<span class="meta-nav">&larr;</span> %title','next_text'=>'%title <span class="meta-nav">&rarr;</span>'));?></article></main><?php endwhile;get_footer();?>
